extension AudioSessionCategory {
    private typealias T = LocalizedText

    var generatedTitle: LocalizedText {
        switch self {
        case .firstSteps: return T(fr: "Premiers pas", en: "First steps", de: "Erste Schritte", es: "Primeros pasos", ja: "はじめての瞑想", ko: "명상 첫걸음")
        case .stressSOS: return T(fr: "SOS stress", en: "Stress SOS", de: "Stress-SOS", es: "SOS estrés", ja: "ストレスSOS", ko: "스트레스 SOS")
        case .workBreak: return T(fr: "Au travail", en: "At work", de: "Bei der Arbeit", es: "En el trabajo", ja: "仕事のなかで", ko: "일하는 중에")
        case .anxiety: return T(fr: "Anxiété & émotions", en: "Anxiety & emotions", de: "Angst & Gefühle", es: "Ansiedad y emociones", ja: "不安と感情", ko: "불안 & 감정")
        case .sleep: return T(fr: "Sommeil", en: "Sleep", de: "Schlaf", es: "Sueño", ja: "睡眠", ko: "수면")
        case .morning: return T(fr: "Matin & énergie", en: "Morning & energy", de: "Morgen & Energie", es: "Mañana y energía", ja: "朝とエネルギー", ko: "아침 & 에너지")
        case .bodyRelax: return T(fr: "Corps & détente", en: "Body & relaxation", de: "Körper & Entspannung", es: "Cuerpo y relajación", ja: "からだとリラックス", ko: "몸 & 이완")
        case .selfCompassion: return T(fr: "Bienveillance", en: "Kindness", de: "Selbstmitgefühl", es: "Bondad contigo", ja: "セルフ・コンパッション", ko: "자기 자비")
        case .focus: return T(fr: "Concentration & clarté", en: "Focus & clarity", de: "Fokus & Klarheit", es: "Concentración y claridad", ja: "集中と明晰さ", ko: "집중 & 명료함")
        case .stressScience: return T(fr: "Le stress décodé", en: "Stress decoded", de: "Stress verstehen", es: "El estrés, descifrado", ja: "ストレスを知る", ko: "스트레스 해독")
        }
    }

    var generatedSubtitle: LocalizedText {
        switch self {
        case .firstSteps: return T(fr: "Apprends à méditer en 7 jours, quelques minutes par jour", en: "Learn to meditate in 7 days, a few minutes a day", de: "In 7 Tagen meditieren lernen – ein paar Minuten täglich", es: "Aprende a meditar en 7 días, unos minutos al día", ja: "1日数分、7日間で瞑想の基本が身につく", ko: "하루 몇 분, 7일 만에 명상의 기본 익히기")
        case .stressSOS: return T(fr: "1 à 7 minutes pour redescendre, tout de suite", en: "1 to 7 minutes to come back down, right now", de: "1 bis 7 Minuten, um sofort runterzukommen", es: "De 1 a 7 minutos para bajar revoluciones, ya", ja: "今すぐ落ち着くための1〜7分", ko: "지금 바로 가라앉히는 1~7분")
        case .workBreak: return T(fr: "Souffler entre deux réunions, finir ta journée léger", en: "Breathe between meetings, finish your day lighter", de: "Zwischen Meetings durchatmen, leichter Feierabend machen", es: "Respira entre reuniones y termina el día más ligero", ja: "会議の合間にひと息、軽やかに一日を終える", ko: "회의 사이에 숨 돌리고, 가볍게 하루 마치기")
        case .anxiety: return T(fr: "Moins lutter contre ce que tu ressens, et ça s'apaise", en: "Stop fighting what you feel, and it softens", de: "Weniger gegen Gefühle kämpfen – dann wird es leichter", es: "Deja de pelear con lo que sientes y se suaviza", ja: "感情と闘うのをやめると、やわらいでいく", ko: "감정과 싸우지 않으면 누그러져요")
        case .sleep: return T(fr: "Lâcher la journée et glisser vers le sommeil", en: "Let go of the day and drift off", de: "Den Tag loslassen und hinübergleiten", es: "Suelta el día y déjate llevar por el sueño", ja: "一日を手放して、眠りへすべりこむ", ko: "하루를 내려놓고 잠으로 스며들기")
        case .morning: return T(fr: "Bien démarrer, sans te lever déjà stressé", en: "Start well, without waking up stressed", de: "Gut starten, ohne schon gestresst aufzustehen", es: "Empieza bien, sin levantarte ya estresado", ja: "起きた瞬間からのストレスなしに、よいスタートを", ko: "일어나자마자 스트레스받지 않고 잘 시작하기")
        case .bodyRelax: return T(fr: "Là où le stress s'accroche : nuque, ventre, mâchoire… on relâche", en: "Where stress clings: neck, belly, jaw… let it go", de: "Wo Stress festsitzt – Nacken, Bauch, Kiefer – loslassen", es: "Donde se agarra el estrés: cuello, vientre, mandíbula… suéltalo", ja: "首、お腹、あご…ストレスが居座る場所をゆるめる", ko: "목, 배, 턱… 스트레스가 붙어 있는 곳을 풀어주기")
        case .selfCompassion: return T(fr: "Être de ton côté, surtout quand c'est dur", en: "Be on your own side, especially when it's hard", de: "Auf deiner Seite stehen – gerade wenn es schwer ist", es: "Estar de tu lado, sobre todo cuando cuesta", ja: "つらいときこそ、自分の味方に", ko: "힘들 때일수록 내 편이 되어주기")
        case .focus: return T(fr: "Entraîner ton attention et voir plus clair", en: "Train your attention and think more clearly", de: "Aufmerksamkeit trainieren, klarer denken", es: "Entrena tu atención y piensa con más claridad", ja: "注意力を鍛え、もっとクリアに", ko: "주의력을 기르고 더 맑게 생각하기")
        case .stressScience: return T(fr: "Comprendre ce qui se passe dans ton corps, et pratiquer", en: "Understand what's happening in your body, then practice", de: "Verstehen, was im Körper passiert – und üben", es: "Entiende lo que pasa en tu cuerpo y practica", ja: "からだで何が起きているかを知り、実践する", ko: "몸에서 무슨 일이 일어나는지 이해하고 실천하기")
        }
    }

}
